using IntIt = std::istream_iterator<int>;

// Active iterator linked to the input source (e.g., std::cin)
IntIt stream_it(std::cin);

// Default-constructed iterator signifies End-Of-Stream (EOS)
IntIt eos_marker;

int total = 0;

// Detection core: Comparison against the default-constructed iterator
while (stream_it != eos_marker) {
    total += *stream_it; // Value dereferenced

    // Advance iterator: triggers the next read operation
    ++stream_it;
}
// EOS state reached when loop condition fails
